pub(super) fn expr_type_layout<'a>(
    expr: &SpannedExpr,
    locals: Option<&HashMap<String, LocalInfo>>,
    st: &SymbolTable,
    type_layouts: &'a crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<&'a crate::sema::type_layout::TypeLayout> {
    match operator_expr_type_info(expr, locals, st, Some(type_layouts)) {
        Some(crate::sema::symtab::TypeInfo::Derived(name))
        | Some(crate::sema::symtab::TypeInfo::Class(name)) => type_layouts.get(&name),
        _ => None,
    }
}

#[derive(Clone)]
pub(super) enum ScalarAllocSourceCopyPlan {
    Static(String),
    Dynamic(String),
}

pub(super) fn expr_scalar_alloc_source_copy_plan(
    expr: &SpannedExpr,
    locals: &HashMap<String, LocalInfo>,
    st: &SymbolTable,
    type_layouts: &crate::sema::type_layout::TypeLayoutRegistry,
) -> Option<ScalarAllocSourceCopyPlan> {
    if let Some(layout) = expr_type_layout(expr, Some(locals), st, type_layouts) {
        if !layout.is_abstract {
            return Some(ScalarAllocSourceCopyPlan::Static(layout.name.clone()));
        }
    }
    operator_expr_type_info(expr, Some(locals), st, Some(type_layouts))
        .and_then(|ti| abstract_layout_base_type(type_layouts, &ti))
        .map(ScalarAllocSourceCopyPlan::Dynamic)
}

